-- CampusSpace database schema
-- Platform: Cloudflare D1 (SQLite)
-- Purpose: campus users, buildings, rooms, schedules, and reservations.

PRAGMA foreign_keys = ON;

-- 1. USER ACCOUNTS
-- Passwords are stored as salted hashes generated by worker.js, never as plain text.
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT NOT NULL UNIQUE COLLATE NOCASE,
    full_name TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('admin', 'professor', 'officer')),
    section TEXT,
    position TEXT,
    salt TEXT NOT NULL,
    password_hash TEXT NOT NULL,
    iterations INTEGER NOT NULL DEFAULT 100000,
    active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 2. LOGIN SESSIONS
-- The API stores a hash of the session token, not the raw token.
CREATE TABLE IF NOT EXISTS sessions (
    token_hash TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 3. CAMPUS BUILDINGS
CREATE TABLE IF NOT EXISTS buildings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    floors INTEGER NOT NULL DEFAULT 1 CHECK (floors >= 1),
    map_x REAL NOT NULL,
    map_z REAL NOT NULL,
    color TEXT NOT NULL DEFAULT '#a5c9f5',
    category TEXT NOT NULL DEFAULT 'academic'
);

-- 4. ROOMS / CLASSROOMS
CREATE TABLE IF NOT EXISTS rooms (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    building_id INTEGER NOT NULL REFERENCES buildings(id),
    room_number TEXT NOT NULL,
    floor INTEGER NOT NULL CHECK (floor >= 1),
    capacity INTEGER NOT NULL DEFAULT 40 CHECK (capacity >= 0),
    kind TEXT NOT NULL DEFAULT 'classroom',
    active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
    UNIQUE (building_id, room_number)
);

-- 5. OFFICIAL RECURRING CLASS SCHEDULES
-- weekday: 0 = Sunday, 1 = Monday, ... 6 = Saturday.
CREATE TABLE IF NOT EXISTS schedules (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    subject TEXT NOT NULL,
    section TEXT NOT NULL,
    professor_id INTEGER REFERENCES users(id),
    room_id INTEGER NOT NULL REFERENCES rooms(id),
    weekday INTEGER NOT NULL CHECK (weekday BETWEEN 0 AND 6),
    start_time TEXT NOT NULL,
    end_time TEXT NOT NULL,
    CHECK (start_time < end_time)
);

-- 6. ONE-TIME CLASSROOM RESERVATION REQUESTS
CREATE TABLE IF NOT EXISTS reservations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    room_id INTEGER NOT NULL REFERENCES rooms(id),
    requested_by INTEGER NOT NULL REFERENCES users(id),
    section TEXT NOT NULL,
    purpose TEXT NOT NULL,
    date TEXT NOT NULL,
    start_time TEXT NOT NULL,
    end_time TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'approved', 'rejected')),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    reviewed_by INTEGER REFERENCES users(id),
    CHECK (start_time < end_time)
);

-- 7. ADMINISTRATOR ROOM CLOSURES / MAINTENANCE BLOCKS
CREATE TABLE IF NOT EXISTS room_unavailability (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    room_id INTEGER NOT NULL REFERENCES rooms(id),
    date TEXT NOT NULL,
    start_time TEXT NOT NULL,
    end_time TEXT NOT NULL,
    reason TEXT NOT NULL,
    created_by INTEGER REFERENCES users(id),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (start_time < end_time)
);

-- Indexes help the API check schedules and reservations by room/time.
CREATE INDEX IF NOT EXISTS idx_schedules_room_time
    ON schedules (room_id, weekday, start_time, end_time);
CREATE INDEX IF NOT EXISTS idx_reservations_room_time
    ON reservations (room_id, date, start_time, end_time, status);
CREATE INDEX IF NOT EXISTS idx_reservations_requester
    ON reservations (requested_by, created_at);

