-- PANCHO HALL: rooms 100–124 on floor 1; rooms 200–234 on floor 2.
WITH RECURSIVE room_numbers(n) AS (
    SELECT 100
    UNION ALL SELECT n + 1 FROM room_numbers WHERE n < 124
)
INSERT OR IGNORE INTO rooms (building_id, room_number, floor)
SELECT id, CAST(n AS TEXT), 1
FROM buildings CROSS JOIN room_numbers
WHERE buildings.name = 'Pancho Hall';

WITH RECURSIVE room_numbers(n) AS (
    SELECT 200
    UNION ALL SELECT n + 1 FROM room_numbers WHERE n < 234
)
INSERT OR IGNORE INTO rooms (building_id, room_number, floor)
SELECT id, CAST(n AS TEXT), 2
FROM buildings CROSS JOIN room_numbers
WHERE buildings.name = 'Pancho Hall';

INSERT OR IGNORE INTO rooms (building_id, room_number, floor, kind)
SELECT id, 'AVR', 1, 'audiovisual'
FROM buildings WHERE name = 'Pancho Hall';

INSERT OR IGNORE INTO rooms (building_id, room_number, floor, kind)
SELECT id, 'Library', 1, 'library'
FROM buildings WHERE name = 'Pancho Hall';

-- HANGAR: rooms 001–006.
WITH RECURSIVE room_numbers(n) AS (
    SELECT 1
    UNION ALL SELECT n + 1 FROM room_numbers WHERE n < 6
)
INSERT OR IGNORE INTO rooms (building_id, room_number, floor)
SELECT id, printf('%03d', n), 1
FROM buildings CROSS JOIN room_numbers
WHERE buildings.name = 'Hangar';

-- MPG: rooms MPG 001–MPG 003.
WITH RECURSIVE room_numbers(n) AS (
    SELECT 1
    UNION ALL SELECT n + 1 FROM room_numbers WHERE n < 3
)
INSERT OR IGNORE INTO rooms (building_id, room_number, floor)
SELECT id, 'MPG ' || printf('%03d', n), 1
FROM buildings CROSS JOIN room_numbers
WHERE buildings.name = 'MPG';

